// Simplified structure of a Wireshark JSON export
export interface WiresharkPacket {
  _index: string;
  _type: string;
  _score:  number | null;
  _source: {
    layers: {
      frame: {
        "frame.number": string;
        "frame.time": string;
        "frame.len": string;
        "frame.protocols": string;
        [key: string]: any;
      };
      ip?: {
        "ip.src": string;
        "ip.dst": string;
        "ip.proto": string;
        [key: string]: any;
      };
      tcp?: {
        "tcp.srcport": string;
        "tcp.dstport": string;
        "tcp.flags": string;
        [key: string]: any;
      };
      udp?: {
        "udp.srcport": string;
        "udp.dstport": string;
        [key: string]: any;
      };
      http?: {
        "http.request.method"?: string;
        "http.request.uri"?: string;
        "http.user_agent"?: string;
        [key: string]: any;
      };
      [key: string]: any;
    };
  };
}

export interface ProcessedPacket {
  id: number;
  time: string;
  source: string;
  destination: string;
  protocol: string;
  length: number;
  info: string;
  raw: any;
}

export interface NetworkStats {
  totalPackets: number;
  protocolCounts: { name: string; value: number }[];
  topTalkers: { ip: string; count: number }[];
  startTime: string;
  endTime: string;
  suspiciousIPs: string[];
}

export enum AppState {
  UPLOAD = 'UPLOAD',
  DASHBOARD = 'DASHBOARD',
}

import { GoogleGenAI } from "@google/genai";
import { NetworkStats, ProcessedPacket } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeNetworkTraffic = async (
  stats: NetworkStats,
  samplePackets: ProcessedPacket[]
): Promise<string> => {
  try {
    const model = "gemini-3-flash-preview";

    // Construct a summarized prompt to avoid huge token usage
    const summary = JSON.stringify({
      totalPackets: stats.totalPackets,
      protocols: stats.protocolCounts.slice(0, 10), // Top 10 protocols
      topTalkers: stats.topTalkers.slice(0, 10), // Top 10 IPs
      timeRange: `${stats.startTime} - ${stats.endTime}`,
    }, null, 2);

    const packetSample = JSON.stringify(samplePackets.map(p => ({
      time: p.time,
      src: p.source,
      dst: p.destination,
      proto: p.protocol,
      info: p.info
    })), null, 2);

    const prompt = `
      Você é um especialista sênior em segurança cibernética e redes (Network Analyst).

      Analise o seguinte resumo de tráfego de rede importado do Wireshark (formato JSON):

      ESTATÍSTICAS GERAIS:
      ${summary}

      AMOSTRA DE PACOTES (Primeiros 15 + Aleatórios):
      ${packetSample}

      Por favor, forneça um relatório em formato Markdown (PT-BR) cobrindo:
      1. **Visão Geral do Tráfego**: O que está acontecendo nesta rede? É navegação web, transferência de arquivos, ataque, etc?
      2. **Anomalias Potenciais**: Existe algo suspeito? (Ex: Portas estranhas, muitos erros, protocolos inseguros como HTTP/Telnet, IPs desconhecidos com alto volume).
      3. **Recomendações de Segurança**: O que o usuário deve investigar ou bloquear?
      4. **Explicação para Iniciantes**: Explique de forma didática o que os protocolos principais encontrados fazem.

      Seja direto, técnico mas acessível. Use formatação rica (negrito, listas).
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
    });

    return response.text || "Não foi possível gerar a análise.";
  } catch (error) {
    console.error("Erro na análise do Gemini:", error);
    return "Ocorreu um erro ao conectar com a IA. Verifique sua chave de API ou tente novamente mais tarde.";
  }
};

import { WiresharkPacket, ProcessedPacket, NetworkStats } from '../types';

export const parseWiresharkJSON = (jsonData: any[]): { packets: ProcessedPacket[], stats: NetworkStats } => {
  const processed: ProcessedPacket[] = [];
  const protocolMap = new Map<string, number>();
  const ipMap = new Map<string, number>();

  jsonData.forEach((item: WiresharkPacket) => {
    const layers = item._source?.layers;
    if (!layers || !layers.frame) return;

    const frame = layers.frame;
    const ip = layers.ip;

    // Determine info string based on protocols
    let info = "";
    let src = "Ethernet";
    let dst = "Broadcast";
    let proto = "ETH";

    // Extract Protocols
    const protocols = frame["frame.protocols"]?.split(':').reverse() || ["Unknown"];
    proto = protocols[0].toUpperCase(); // Most specific protocol usually last in stack (but reversed here to be first) -> Actually wireshark lists eth:ip:tcp. So last is specific.
    // Let's fix protocol logic: Wireshark "frame.protocols" is like "eth:ethertype:ip:tcp:tls". We want the last one usually.
    const protoStack = frame["frame.protocols"]?.split(':') || [];
    proto = protoStack.length > 0 ? protoStack[protoStack.length - 1].toUpperCase() : "ETH";

    // Extract IP
    if (ip) {
      src = ip["ip.src"];
      dst = ip["ip.dst"];
      ipMap.set(src, (ipMap.get(src) || 0) + 1);
      ipMap.set(dst, (ipMap.get(dst) || 0) + 1);
    } else if (layers.ipv6) {
        src = layers.ipv6["ipv6.src"];
        dst = layers.ipv6["ipv6.dst"];
        ipMap.set(src, (ipMap.get(src) || 0) + 1);
        ipMap.set(dst, (ipMap.get(dst) || 0) + 1);
    } else if (layers.eth) {
        src = layers.eth["eth.src"];
        dst = layers.eth["eth.dst"];
    }

    // Basic Info construction
    if (layers.http) {
        info = `${layers.http["http.request.method"] || 'RESPONSE'} ${layers.http["http.request.uri"] || ''}`;
    } else if (layers.dns) {
        // Checking for standard query name if available, heavily dependent on wireshark export detail
        const query = Object.keys(layers.dns).find(k => k.includes("qry.name"));
        if(query) info = `DNS Query: ${layers.dns[query]}`;
        else info = "DNS Transaction";
    } else if (layers.tcp) {
        info = `${layers.tcp["tcp.srcport"]} -> ${layers.tcp["tcp.dstport"]} [${proto}]`;
    } else if (layers.udp) {
        info = `${layers.udp["udp.srcport"]} -> ${layers.udp["udp.dstport"]} [${proto}]`;
    } else {
        info = `Len: ${frame["frame.len"]}`;
    }

    protocolMap.set(proto, (protocolMap.get(proto) || 0) + 1);

    processed.push({
      id: parseInt(frame["frame.number"]),
      time: frame["frame.time"],
      source: src,
      destination: dst,
      protocol: proto,
      length: parseInt(frame["frame.len"]),
      info: info,
      raw: item
    });
  });

  // Sort and format stats
  const protocolCounts = Array.from(protocolMap.entries())
    .map(([name, value]) => ({ name, value }))
    .sort((a, b) => b.value - a.value);

  const topTalkers = Array.from(ipMap.entries())
    .map(([ip, count]) => ({ ip, count }))
    .sort((a, b) => b.count - a.count);

  const stats: NetworkStats = {
    totalPackets: processed.length,
    protocolCounts,
    topTalkers,
    startTime: processed[0]?.time || '',
    endTime: processed[processed.length - 1]?.time || '',
    suspiciousIPs: [] // To be filled by simple heuristic or AI
  };

  return { packets: processed, stats };
};

import React, { useCallback, useState } from 'react';
import { Upload, FileJson, AlertTriangle } from 'lucide-react';

interface UploadSectionProps {
  onDataLoaded: (data: any) => void;
  isLoading: boolean;
}

const UploadSection: React.FC<UploadSectionProps> = ({ onDataLoaded, isLoading }) => {
  const [error, setError] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleFile = (file: File) => {
    if (file.type !== "application/json" && !file.name.endsWith('.json')) {
      setError("Por favor, envie um arquivo JSON exportado do Wireshark.");
      return;
    }
    setError(null);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        if (!Array.isArray(json)) {
          throw new Error("Formato inválido. Esperado um array de pacotes.");
        }
        onDataLoaded(json);
      } catch (err) {
        setError("Erro ao ler o arquivo JSON. Certifique-se que foi exportado corretamente do Wireshark.");
      }
    };
    reader.readAsText(file);
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, []);

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] p-4 animate-fade-in">
        <div className="max-w-2xl w-full text-center mb-8">
            <h1 className="text-4xl font-bold text-white mb-4 tracking-tight">
                Análise de Rede <span className="text-cyan-400">Inteligente</span>
            </h1>
            <p className="text-slate-400 text-lg">
                Importe seus dados do Wireshark e deixe a IA encontrar as ameaças para você.
            </p>
        </div>

      <div 
        className={`w-full max-w-2xl p-12 rounded-3xl border-2 border-dashed transition-all duration-300 backdrop-blur-sm
          ${isDragging 
            ? 'border-cyan-400 bg-cyan-400/10' 
            : 'border-slate-700 bg-slate-800/50 hover:border-cyan-500/50'
          }`}
        onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={onDrop}
      >
        <div className="flex flex-col items-center text-center space-y-4">
            {isLoading ? (
                <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-cyan-400"></div>
            ) : (
                <>
                    <div className="p-4 rounded-full bg-slate-800 ring-1 ring-slate-700">
                        <Upload className="w-10 h-10 text-cyan-400" />
                    </div>
                    <div>
                        <p className="text-xl font-medium text-white">Arraste seu arquivo JSON aqui</p>
                        <p className="text-slate-400 mt-2">ou clique para selecionar</p>
                    </div>
                    <label className="cursor-pointer">
                        <span className="px-6 py-2 rounded-lg bg-cyan-500 hover:bg-cyan-600 text-white font-medium transition-colors shadow-lg shadow-cyan-500/20">
                            Selecionar Arquivo
                        </span>
                        <input 
                            type="file" 
                            className="hidden" 
                            accept=".json" 
                            onChange={(e) => e.target.files && handleFile(e.target.files[0])}
                        />
                    </label>
                </>
            )}
        </div>
      </div>

      {error && (
        <div className="mt-4 p-4 bg-red-500/10 border border-red-500/50 rounded-lg flex items-center gap-2 text-red-200">
          <AlertTriangle className="w-5 h-5" />
          <span>{error}</span>
        </div>
      )}

      <div className="mt-12 bg-slate-800/50 p-6 rounded-xl max-w-2xl w-full border border-slate-700">
        <h3 className="text-white font-semibold flex items-center gap-2 mb-3">
            <FileJson className="w-5 h-5 text-yellow-400" />
            Como exportar do Wireshark?
        </h3>
        <ol className="list-decimal list-inside text-slate-400 space-y-2 text-sm">
            <li>Abra sua captura (.pcap) no Wireshark.</li>
            <li>Vá em <span className="text-cyan-300 font-mono">File &gt; Export Packet Dissections &gt; As JSON...</span></li>
            <li>Salve o arquivo e arraste-o para a área acima.</li>
            <li>Recomendamos arquivos menores que 50MB para melhor performance no navegador.</li>
        </ol>
      </div>
    </div>
  );
};

