    if (!stats || packets.length === 0) return;
    setIsAnalyzing(true);

    // Create a sample of packets: first 15 + 15 random ones from the middle
    const sample = [
        ...packets.slice(0, 15),
        ...packets.sort(() => 0.5 - Math.random()).slice(0, 15)
